import json,glob,re,ast,os
# signatures
sig={}
for f in glob.glob('oekoinvest_app/**/*.py',recursive=True):
    try:t=ast.parse(open(f,encoding='utf-8').read())
    except Exception as e: print("PARSE",f,e); continue
    for n in t.body:
        if isinstance(n,ast.FunctionDef) and n.name.startswith('oekoinvest_'):
            a=n.args; sig[n.name]=(len(a.args)-len(a.defaults),len(a.args),[x.arg for x in a.args])
files=glob.glob('oekoinvest_app/**/*.json',recursive=True)+glob.glob('oekoinvest_app/**/*.html',recursive=True)
for f in files:
    s=open(f,encoding='utf-8').read()
    for m in re.finditer(r'(oekoinvest_\w+)\(',s):
        name=m.group(1)
        if name not in sig: continue
        # extract balanced args
        i=m.end(); depth=1; j=i
        while j<len(s) and depth:
            if s[j]=='(':depth+=1
            elif s[j]==')':depth-=1
            j+=1
        arg=s[i:j-1].replace('\\"','"').replace('\\n',' ')
        try: c=ast.parse(f"f({arg})",mode='eval').body
        except Exception: continue
        npos=len(c.args); kws=[k.arg for k in c.keywords]
        req,tot,names=sig[name]
        if npos+len(kws)<req or npos>tot or any(k not in names for k in kws): print(f,name,arg[:80],sig[name])
